```javascript
const fs = require('fs');
const yaml = require('yaml');

function yaml_to_json(yamlFilePath) {
  try {
    if (!yamlFilePath || typeof yamlFilePath !== 'string') {
      throw new Error('Invalid YAML file path');
    }

    // Ensure the path is absolute to prevent directory traversal
    const absolutePath = fs.resolve(yamlFilePath);
    const baseDir = process.cwd();

    // Check if the resolved path is within the current working directory
    if (!absolutePath.startsWith(baseDir)) {
      throw new Error('File path is outside the allowed directory');
    }

    // Read the YAML file
    const yamlContent = fs.readFileSync(absolutePath, 'utf8');

    // Parse YAML content
    const parsedYaml = yaml.parse(yamlContent);

    // Convert to JSON string
    return JSON.stringify(parsedYaml, null, 2);
  } catch (error) {
    // Return error message starting with 'Error: '
    return `Error: ${error.message}`;
  }
}
```

